const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const centralOklahoma = ee.Geometry.Point([-97.5, 35.5]);
  const northernTexas = ee.Geometry.Point([-97.0, 33.5]);

  const startDate = '2007-08-10';
  const endDate = '2007-08-21'; // Exclusive end date for 10-20 range

  // 2. Data Acquisition
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  const oklaCol = chirps.filterBounds(centralOklahoma);
  const texasCol = chirps.filterBounds(northernTexas);

  const oklaSize = oklaCol.size().getInfo();
  const texasSize = texasCol.size().getInfo();

  console.log(`Oklahoma Images: ${oklaSize}`);
  console.log(`Texas Images: ${texasSize}`);

  if (oklaSize === 0 || texasSize === 0) {
    console.log("No data found for one or both locations.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum rainfall over the period
  const oklaTotal = oklaCol.sum();
  const texasTotal = texasCol.sum();

  // 4. Calculate total rainfall
  const oklaStats = oklaTotal.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: centralOklahoma,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const texasStats = texasTotal.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: northernTexas,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const oklaRainfall = oklaStats.precipitation;
  const texasRainfall = texasStats.precipitation;

  console.log(`Oklahoma Rainfall: ${oklaRainfall !== null ? oklaRainfall.toFixed(2) : 'null'} mm`);
  console.log(`Texas Rainfall: ${texasRainfall !== null ? texasRainfall.toFixed(2) : 'null'} mm`);

  // 5. Validation & Final Answer
  if (oklaRainfall === null || texasRainfall === null || 
      oklaRainfall === undefined || texasRainfall === undefined) {
    console.log("Calculation failed - null result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (isNaN(oklaRainfall) || isNaN(texasRainfall)) {
    console.log("Calculation failed - NaN result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (oklaRainfall > texasRainfall) {
    console.log("Central Oklahoma has more rainfall than northern Texas.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Central Oklahoma does NOT have more rainfall than northern Texas.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
